function App() {
  const [text, setText] = useState('');
  const renderCount = useRef(0);
  renderCount.current += 1; // mutates without re-rendering
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <input value={text} onChange={e => setText(e.target.value)} placeholder="Type..." />
      <p>Renders so far: {renderCount.current}</p>
    </div>
  );
}

const FancyInput = React.forwardRef(function FancyInput(props, ref) {
  const inputRef = useRef(null);
  useImperativeHandle(ref, () => ({
    focus: () => inputRef.current.focus(),
    clear: () => { inputRef.current.value = ''; }
  }));
  return <input ref={inputRef} placeholder="fancy input" />;
});

